const defaultTimers={set:(callback,ms)=>setTimeout(callback,ms),clear:(handle)=>clearTimeout(handle)};
export function connectEventStream(options){
const found=options.EventSource??globalThis.EventSource;
if(!found)
throw new TypeError('EventSource is not available; pass one in options.');
const Source=found;
const timers=options.timers??defaultTimers;
const random=options.random??Math.random;
const initialMs=options.retry?.initialMs??500;
const maxMs=options.retry?.maxMs??15000;
if(!(initialMs>0)||!(maxMs>=initialMs))
throw new RangeError('retry');
const param=options.cursorParam??'after';
const base=typeof location==='undefined'?undefined:location.href;
let source=null;
let timer=null;
let attempt=0;
let closed=false;
const report=(status,delayMs)=>options.onStatus?.(status,delayMs===undefined?{attempt}:{attempt,delayMs});
const detach=()=>{
if(!source)
return;
source.onopen=source.onmessage=source.onerror=null;
source.close();
source=null;
};
const retry=()=>{
detach();
if(closed)
return;
const delayMs=Math.round(Math.min(maxMs,initialMs*2**attempt)*(0.5+random()/2));
attempt+=1;
report('retrying',delayMs);
timer=timers.set(open,delayMs);
};
function open(){
timer=null;
if(closed)
return;
const url=new URL(String(options.url),base);
url.searchParams.set(param,String(options.store.getSnapshot().cursor));
report('connecting');
const next=new Source(url.href,options.withCredentials?{withCredentials:true}:undefined);
source=next;
next.onopen=()=>{
attempt=0;
report('open');
};
next.onmessage=(message)=>{
let frame;
try{
frame=JSON.parse(message.data);
}
catch{
return;
}
const mapped=options.map?options.map(frame):frame;
if(mapped===null||mapped===undefined)
return;
options.store.apply(Array.isArray(mapped)?mapped:[mapped]);
if(options.store.getSnapshot().gap)
retry();
};
next.onerror=retry;
}
const close=()=>{
if(closed)
return;
closed=true;
if(timer!==null)
timers.clear(timer);
timer=null;
detach();
options.signal?.removeEventListener('abort',close);
report('closed');
};
if(options.signal?.aborted){
closed=true;
report('closed');
return()=>{};
}
options.signal?.addEventListener('abort',close,{once:true});
open();
return close;
}
